import React from 'react';

function JobList({ jobs }) {
  return (
    <div>
      <h2>Job List</h2>
      <ul>
        {jobs.map((job) => (
          <li key={job.id}>
            <strong>{job.title}</strong> at {job.company} - ${job.salary} ({job.sector})
          </li>
        ))}
      </ul>
    </div>
  );
}

export default JobList;
